import { inject, type InjectionKey } from 'vue';
import type { Props as ButtonProps } from '../button/Button.vue';

export type SplitButtonSize = Exclude<
  NonNullable<ButtonProps['size']>,
  'icon-sm' | 'icon-md' | 'icon-lg'
>;
export type SplitButtonVariant = Exclude<NonNullable<ButtonProps['variant']>, 'link'>;
type SplitButtonContextValue = { size: () => SplitButtonSize; variant: () => SplitButtonVariant };
export const SplitButtonContextKey: InjectionKey<SplitButtonContextValue> =
  Symbol('SplitButtonContext');
export const useSplitButtonContext = (componentName: string) => {
  const context = inject(SplitButtonContextKey);
  if (!context) throw new Error(`${componentName} must be used within SplitButton.`);
  return context;
};

export { default as SplitButton } from './SplitButton.vue';
export { default as SplitButtonAction } from './SplitButtonAction.vue';
export { default as SplitButtonTrigger } from './SplitButtonTrigger.vue';
export { default as SplitButtonPositioner } from './SplitButtonPositioner.vue';
export { default as SplitButtonContent } from './SplitButtonContent.vue';

@layer moduix.components {
  .root {
    display: inline-flex;
    align-items: stretch;
  }

  .action {
    border-start-end-radius: 0;
    border-end-end-radius: 0;
  }

  .trigger {
    position: relative;
    min-width: 0;
    margin-inline-start: calc(
      var(--moduix-button-border-width, var(--moduix-border-width-sm)) * -1
    );
    border-start-start-radius: 0;
    border-end-start-radius: 0;
  }

  .trigger::before {
    content: '';
    position: absolute;
    inset-block: var(--moduix-split-button-separator-inset, var(--moduix-spacing-1-5));
    inset-inline-start: var(--moduix-split-button-separator-offset, 0);
    width: var(--moduix-split-button-separator-width, var(--moduix-border-width-sm));
    background-color: var(--moduix-split-button-separator-color, currentColor);
    opacity: var(--moduix-split-button-separator-opacity, 0.16);
    pointer-events: none;
  }

  .trigger[data-variant='outline']::before,
  .trigger[data-variant='destructive-outline']::before {
    opacity: 0;
  }

  .trigger[data-size='xs'] {
    padding-inline: var(--moduix-split-button-trigger-padding-x-xs, var(--moduix-spacing-2));
  }

  .trigger[data-size='sm'] {
    padding-inline: var(--moduix-split-button-trigger-padding-x-sm, var(--moduix-spacing-2-5));
  }

  .trigger[data-size='md'] {
    padding-inline: var(--moduix-split-button-trigger-padding-x-md, var(--moduix-spacing-3));
  }

  .trigger[data-size='lg'] {
    padding-inline: var(--moduix-split-button-trigger-padding-x-lg, var(--moduix-spacing-3-5));
  }

  .trigger[data-size='xl'] {
    padding-inline: var(--moduix-split-button-trigger-padding-x-xl, var(--moduix-spacing-4));
  }

  @media (prefers-reduced-motion: no-preference) {
    .action:active:not([data-variant='link']),
    .trigger:active:not([data-variant='link']) {
      transform: none;
    }
  }
}
